WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_growth_rate'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '增长率计算', 'kp-xingce-data-growth-rate', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "增长率计算"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "反映数据变化快慢的相对量指标，也称增速、增幅。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题干常见问法：“2023年相比2022年，增长了百分之多少？”或“2023年的增速是多少？”特征是求百分比（%）。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "增长率 = \\frac{增长量}{基期量} = \\frac{现期量 - 基期量}{基期量} = \\frac{现期量}{基期量} - 1"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[明确求增长率] --> B[查找现期量与基期量]\nB --> C{使用哪种算法?}\nC -- 传统法 --> D[先算减法: 现期-基期]\nD --> E[再算除法: 差值 / 基期]\nC -- 高效法(推荐) --> F[直接算除法: 现期 / 基期]\nF --> G[商减去 1 即为增长率]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年某地销售额 5678 万，2022年为 4321 万。求同比增长率？选项：A. 18.5% B. 24.3% C. 31.4% D. 38.6%"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列式：5678 ÷ 4321 - 1。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分母截位：分母截三位 432，式子变为 5678 ÷ 432。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "直除：首位商 1，次位商 3（13×432=5616），第三位商 1。商为 1.31...。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "减去 1：1.31 - 1 = 31%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选 C。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "名词陷阱（降幅）：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "增长率=增速=增幅。即使是负数（如-5%），也叫负增长率。但如果题目问“降幅是多少”，你要用 (基期-现期)/基期，算出来是一个正数(5%)。绝对不能把降幅写成负数！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "强化“先除后减一”的习惯。遇到减法再除法很容易因为退位借位出错，直接列除法式子能最大限度减少草稿纸上的笔误。"}]}]}$$ AS jsonb), NULL, '增长率计算的核心考点与实战推导。', category_node.id, CAST('["资料分析", "增长率计算"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_growth_rate", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
